def count_cycles(m):
    if m <= 1 or m % 3 == 0:
        return -1  # Invalid input for this problem

    elements = set(range(1, m))
    visited = set()
    cycle_count = 0

    # The permutation is f(x) = 3x mod m
    def f(x):
        return 3 * x % m

    for start_node in elements:
        if start_node not in visited:
            cycle_count += 1
            current = start_node
            while current not in visited:
                visited.add(current)
                current = f(current)

    return cycle_count

# Search for m < 200 such that count_cycles(m) is odd
m_values = []
for m in range(2, 200):
    if m % 3 != 0:
        cycles = count_cycles(m)
        if cycles % 2 != 0:
            m_values.append(m)

# Sort to easily find the second largest
m_values.sort()

print(f"All m < 200 (3 not dividing m) with odd number of cycles: {m_values}")

if len(m_values) >= 2:
    second_largest = m_values[-2]
    print(f"The second largest m is: {second_largest}")
else:
    print("Fewer than two such values found.")

def count_cycles(m):
    """Counts the number of disjoint cycles for the permutation x -> 3x mod m on {1, ..., m-1}."""
    if m <= 1 or m % 3 == 0:
        return -1  # Invalid input based on problem constraints

    visited = [False] * m  # Indices 0 to m-1. We use 1 to m-1.
    cycle_count = 0

    for i in range(1, m):
        if not visited[i]:
            cycle_count += 1
            current = i

            # Trace the cycle
            while not visited[current]:
                visited[current] = True

                # Calculate the next element: 3 * current mod m
                next_val = (3 * current) % m

                # Since 3 is coprime to m, and current is in {1, ..., m-1}, 
                # next_val cannot be 0. It must be in {1, ..., m-1}.
                if next_val == 0:
                     # This should mathematically not happen if m > 1 and 3 not dividing m, 
                     # but as a safeguard in implementation.
                     raise ValueError("Mapping resulted in 0 mod m, unexpected.")

                current = next_val

    return cycle_count

def find_m_solutions():
    candidates = []
    # Check downwards from 199
    for m in range(199, 0, -1):
        if m % 3 != 0:
            cycle_count = count_cycles(m)

            if cycle_count % 2 != 0:
                candidates.append(m)

            # We need the second largest, so we might stop early if we found two.
            if len(candidates) == 2:
                return candidates

    return candidates

solutions = find_m_solutions()
print(f"Found candidates (in decreasing order): {solutions}")
if len(solutions) >= 2:
    print(f"Largest m: {solutions[0]}")
    print(f"Second largest m: {solutions[1]}")
else:
    print("Fewer than two solutions found.")

